	RegisterFailHandler(Fail)
	RunSpecs(t, "FFmpeg Suite")
}

var _ = Describe("ffmpeg", func() {
	BeforeEach(func() {
		_, _ = ffmpegCmd()
		ffmpegPath = "ffmpeg"
		ffmpegErr = nil
	})
	Describe("createFFmpegCommand", func() {
		It("creates a valid command line", func() {
			args := createFFmpegCommand("ffmpeg -i %s -b:a %bk mp3 -", "/music library/file.mp3", 123, 0)
			Expect(args).To(Equal([]string{"ffmpeg", "-i", "/music library/file.mp3", "-b:a", "123k", "mp3", "-"}))
		})
		It("replaces the time offset placeholder", func() {
			args := createFFmpegCommand("ffmpeg -i %s -ss %t -b:a %bk -", "/music library/file.mp3", 123, 42)
			Expect(args).To(Equal([]string{"ffmpeg", "-i", "/music library/file.mp3", "-ss", "42", "-b:a", "123k", "-"}))
		})
		It("adds the time offset after the input when the template has no placeholder", func() {
			args := createFFmpegCommand("ffmpeg -i %s -b:a %bk -", "/music library/file.mp3", 123, 42)
			Expect(args).To(Equal([]string{"ffmpeg", "-i", "/music library/file.mp3", "-ss", "42", "-b:a", "123k", "-"}))
		})
	})

	Describe("createProbeCommand", func() {
		It("creates a valid command line", func() {
			args := createProbeCommand(probeCmd, []string{"/music library/one.mp3", "/music library/two.mp3"})
			Expect(args).To(Equal([]string{"ffmpeg", "-i", "/music library/one.mp3", "-i", "/music library/two.mp3", "-f", "ffmetadata"}))
		})
	})
})

